import json
from datetime import date

TR_AYLAR = {
    "ocak": 1, "şubat": 2, "subat": 2, "mart": 3, "nisan": 4,
    "mayıs": 5, "mayis": 5, "haziran": 6, "temmuz": 7, "ağustos": 8,
    "agustos": 8, "eylül": 9, "eylul": 9, "ekim": 10, "kasım": 11,
    "kasim": 11, "aralık": 12, "aralik": 12,
}


def parse_tutar(v):
    """tutar'ı sayıya çevir; çözümlenemezse None."""
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.replace("₺", "").replace("TL", "").replace(" ", "")
        # küçük t (latin) ve büyük T küçük t için
        s = s.replace("t", "").replace("T", "")
        if not s:
            return None
        try:
            if "." in s and "," in s:
                # . binlik, , ondalık
                num = s.replace(".", "")
                return float(num.replace(",", "."))
            if "," in s:
                num = s.replace(",", ".")
                return float(num)
            if "." in s:
                # yalnız . : noktanın SONRAsındaki rakam sayısı tam 3 ise binlik
                for part in s.split("."):
                    if not part.isdigit():
                        return None
                kuyruk = s.split(".")[-1]
                if len(kuyruk) == 3:
                    return float(s.replace(".", ""))
                return float(s)
            if s.isdigit():
                return float(s)
            return float(s)
        except ValueError:
            return None
    return None


def parse_tarih(v):
    """tarih'i (y,a,g) döndür; çözümlenemezse None."""
    if not isinstance(v, str):
        return None
    s = v.strip()
    # YYYY-MM-DD
    parts = s.split("-")
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        y, a, g = (int(p) for p in parts)
        return (y, a, g)
    # YYYY/MM/DD
    parts = s.split("/")
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        y, a, g = (int(p) for p in parts)
        return (y, a, g)
    # GG.AA.YYYY
    parts = s.split(".")
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        g, a, y = (int(p) for p in parts)
        return (y, a, g)
    # G Ay YYYY
    parts = s.split()
    if len(parts) == 3:
        try:
            g = int(parts[0])
            a = TR_AYLAR.get(parts[1].lower())
            y = int(parts[2])
            if a is not None:
                return (y, a, g)
        except ValueError:
            pass
    return None


def main():
    hatali = 0
    kayitlar = {}  # id -> kayıt (son geçerli kazanır)
    with open("siparisler.jsonl", encoding="utf-8") as f:
        for line in f:
            raw = line
            if not raw.strip():
                continue  # boş satır yok sayılır
            try:
                obj = json.loads(raw)
            except (json.JSONDecodeError, ValueError):
                hatali += 1
                continue
            if not isinstance(obj, dict):
                hatali += 1
                continue
            if not all(k in obj for k in ("id", "musteri", "tutar", "tarih", "durum")):
                hatali += 1
                continue
            tutar = parse_tutar(obj["tutar"])
            if tutar is None:
                hatali += 1
                continue
            tg = parse_tarih(obj["tarih"])
            if tg is None:
                hatali += 1
                continue
            y, a, g = tg
            try:
                date(y, a, g)
            except ValueError:
                hatali += 1
                continue
            musteri = str(obj["musteri"]).strip()
            durum = str(obj["durum"]).strip().lower()
            kayitlar[obj["id"]] = {
                "musteri": musteri,
                "tutar": tutar,
                "ay": f"{y:04d}-{a:02d}",
                "durum": durum,
            }

    iptal_sayisi = 0
    toplam_tutar = 0.0
    aylik = {}
    musteriler = {}
    for k in kayitlar.values():
        if k["durum"] == "iptal":
            iptal_sayisi += 1
            continue
        toplam_tutar += k["tutar"]
        aylik[k["ay"]] = aylik.get(k["ay"], 0.0) + k["tutar"]
        musteriler[k["musteri"]] = musteriler.get(k["musteri"], 0.0) + k["tutar"]

    en_cok = max(musteriler.items(), key=lambda kv: kv[1])[0] if musteriler else None

    ozet = {
        "gecerli_kayit": len(kayitlar),
        "hatali_satir": hatali,
        "iptal_sayisi": iptal_sayisi,
        "toplam_tutar": round(toplam_tutar, 2),
        "aylik": {k: round(v, 2) for k, v in sorted(aylik.items())},
        "en_cok_harcayan": en_cok,
    }
    with open("ozet.json", "w", encoding="utf-8") as f:
        json.dump(ozet, f, ensure_ascii=False, indent=2)
    print(json.dumps(ozet, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

